package com.swordfish.lemuroid.app.shared.game
import android.content.Context
import android.net.Uri
import com.swordfish.libretrodroid.ShaderConfig
import java.io.File
import java.util.zip.ZipInputStream
data class ShaderUniformDef(val name: String, val friendlyName: String, val defaults: FloatArray, val minVal: Float, val maxVal: Float, val labels: List<String> = emptyList())
data class ShaderPassDef(val index: Int, val name: String, val uniforms: List<ShaderUniformDef>)
object CustomShaderLoader {
    private const val F = "custom_shader_pack.zip"
    private const val PREFS = "custom_shader_prefs"
    private const val PRE_FS = "#version 300 es\nprecision highp float;\nin vec2 texCoord;\nuniform sampler2D activeTex;\nuniform float preGamma;\nuniform vec3 preScale;\nuniform vec3 preBias;\nuniform vec3 preDesat;\nout vec4 FragColor;\nvoid main(){\n  vec4 col = texture(activeTex, texCoord);\n  vec3 rgb = pow(max(col.rgb, vec3(0.0)), vec3(1.0 / max(preGamma, 0.05)));\n  rgb = rgb * preScale + preBias;\n  float lum = dot(rgb, vec3(0.299, 0.587, 0.114));\n  rgb = mix(rgb, vec3(lum), clamp(preDesat, 0.0, 1.0));\n  FragColor = vec4(clamp(rgb, 0.0, 1.0), col.a);\n}"
    private val userPresets = mapOf(
        "-1:preGamma" to floatArrayOf(1.000f), "-1:preScale" to floatArrayOf(1.000f, 1.000f, 1.000f),
        "-1:preBias" to floatArrayOf(0.000f, 0.000f, 0.000f), "-1:preDesat" to floatArrayOf(0.000f, 0.000f, 0.000f),
        "-1:none" to floatArrayOf(0f)
    )
    fun saveCustomShaderZip(c: Context, u: Uri) = runCatching { val o = File(c.filesDir, F); c.contentResolver.openInputStream(u)?.use { i -> o.outputStream().use { i.copyTo(it) } }; clearNonPre(c); loadCustomShader(c) != null }.getOrDefault(false)
    fun resetPreprocessing(c: Context) { val sp = c.getSharedPreferences(PREFS, Context.MODE_PRIVATE); val ed = sp.edit(); sp.all.keys.filter { it.startsWith("u_-1_") }.forEach { ed.remove(it) }; ed.apply() } private fun clearNonPre(c: Context) { val sp = c.getSharedPreferences(PREFS, Context.MODE_PRIVATE); val ed = sp.edit(); sp.all.keys.filterNot { it.startsWith("u_-1_") }.forEach { ed.remove(it) }; ed.apply() }
    
    fun clearCustomShader(c: Context) { File(c.filesDir, F).delete(); clearNonPre(c) }
    fun hasCustomShader(c: Context) = File(c.filesDir, F).exists()
    fun getMaxPasses(c: Context) = c.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getInt("max_passes", 10)
    fun setMaxPasses(c: Context, n: Int) { c.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit().putInt("max_passes", n).apply() }
    fun getCompVal(c: Context, pIdx: Int, uName: String, comp: Int, def: Float) = c.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getFloat("u_${pIdx}_${uName}_${comp}", userPresets["${pIdx}:${uName}"]?.getOrNull(comp) ?: def)
    fun setCompVal(c: Context, pIdx: Int, uName: String, comp: Int, v: Float) { c.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit().putFloat("u_${pIdx}_${uName}_${comp}", v).apply() }
    private fun prePassDef() = ShaderPassDef(-1, "Preprocessing", listOf(ShaderUniformDef("preGamma", "Gamma", floatArrayOf(1.000f), 0.100f, 3.000f), ShaderUniformDef("preScale", "Scale", floatArrayOf(1.000f, 1.000f, 1.000f), 0.000f, 2.000f, listOf("R", "G", "B")), ShaderUniformDef("preBias", "Bias", floatArrayOf(0.000f, 0.000f, 0.000f), -1.000f, 1.000f, listOf("R", "G", "B")), ShaderUniformDef("preDesat", "Desaturation", floatArrayOf(0.000f, 0.000f, 0.000f), 0.000f, 1.000f, listOf("R", "G", "B"))))
    fun getShaderName(c: Context): String { val z = File(c.filesDir, F); if (!z.exists()) return "Custom Shader"; return runCatching { val m = readZip(z)["manifest.ini"] ?: return "Custom Shader"; m.lineSequence().map { it.trim() }.firstOrNull { it.startsWith("name=") }?.substringAfter("name=")?.trim()?.takeIf { it.isNotEmpty() } ?: "Custom Shader" }.getOrDefault("Custom Shader") }
    fun getPassDefs(c: Context): List<ShaderPassDef> { val z = File(c.filesDir, F); if (!z.exists()) return emptyList(); return runCatching { val fs = readZip(z); val m = fs["manifest.ini"] ?: return emptyList(); listOf(prePassDef()) + parseDefs(m) }.getOrDefault(emptyList()) }
    fun loadCustomShader(c: Context): ShaderConfig.Custom? { val z = File(c.filesDir, F); if (!z.exists()) return null; return runCatching { val fs = readZip(z); val m = fs["manifest.ini"] ?: return null; parsePasses(c, m, fs) }.getOrNull() }
    private fun readZip(z: File): Map<String, String> { val fs = mutableMapOf<String, String>(); ZipInputStream(z.inputStream().buffered()).use { zi -> var e = zi.nextEntry; while (e != null) { if (!e.isDirectory) fs[e.name.substringAfterLast("/").substringAfterLast("\\")] = zi.readBytes().toString(Charsets.UTF_8); zi.closeEntry(); e = zi.nextEntry } }; return fs }
    private fun parseRaw(m: String): Pair<Map<Int, Map<String, String>>, Map<Pair<Int, String>, Map<String, List<String>>>> { var sec = ""; val pp = mutableMapOf<Int, MutableMap<String, String>>(); val up = mutableMapOf<Pair<Int, String>, MutableMap<String, MutableList<String>>>(); val rPass = Regex("pass\\.(\\d+)$"); val rUni = Regex("pass\\.(\\d+)\\.uniform\\.(.+)$"); m.lineSequence().forEach { rl -> val l = rl.trim(); if (l.isEmpty() || l.startsWith("#") || l.startsWith(";")) return@forEach; if (l.startsWith("[") && l.endsWith("]")) { sec = l.substring(1, l.length - 1).trim(); return@forEach }; val eq = l.indexOf("="); if (eq <= 0) return@forEach; val k = l.substring(0, eq).trim(); val v = l.substring(eq + 1).trim(); rPass.find(sec)?.let { pp.getOrPut(it.groupValues[
1
].toInt()) { mutableMapOf() }[k] = v; return@forEach }; rUni.find(sec)?.let { up.getOrPut(it.groupValues[
1
].toInt() to it.groupValues[
2
].trim()) { mutableMapOf() }.getOrPut(k) { mutableListOf() }.add(v) } }; return pp to up }
    private fun parseDefs(m: String): List<ShaderPassDef> { val (pp, up) = parseRaw(m); return pp.keys.sorted().map { i -> val p = pp[i] ?: emptyMap(); val title = "Pass ${i + 1}: " + (p["friendlyName"] ?: p["fragmentShader"]?.substringBeforeLast(".") ?: "Shader"); val unis = up.filterKeys { it.first == i }.mapNotNull { (pr, uf) -> val t = uf["type"]?.firstOrNull() ?: "float"; val n = when(t){ "float2"->2; "float3"->3; "float4"->4; else->1 }; val defs = List(n) { idx -> if (n == 1) (uf["default"]?.firstOrNull()?.toFloatOrNull() ?: 0f) else (uf["default[$idx]"]?.firstOrNull()?.toFloatOrNull() ?: 0f) }; val arr = userPresets["${i}:${pr.second}"] ?: defs.toFloatArray(); val mn = minOf(uf["min"]?.firstOrNull()?.toFloatOrNull() ?: 0f, arr.minOrNull() ?: 0f); val rawMx = maxOf(uf["max"]?.firstOrNull()?.toFloatOrNull() ?: 1f, arr.maxOrNull() ?: 1f); val mx = if (pr.second == "amount") minOf(rawMx, 0.98f) else rawMx; val fn = uf["friendlyName"]?.firstOrNull() ?: uf["readableName"]?.firstOrNull() ?: pr.second; val lbs = if (arr.size == 2) listOf("X", "Y") else if (arr.size == 3) listOf("R", "G", "B") else emptyList(); ShaderUniformDef(pr.second, fn, arr, mn, mx, lbs) }; ShaderPassDef(i, title, unis) } }     private fun parsePasses(c: Context, m: String, fs: Map<String, String>): ShaderConfig.Custom? { val (pp, up) = parseRaw(m); val preUs = mapOf("preGamma" to floatArrayOf(getCompVal(c, -1, "preGamma", 0, 1.000f)), "preScale" to floatArrayOf(getCompVal(c, -1, "preScale", 0, 1.000f), getCompVal(c, -1, "preScale", 1, 1.000f), getCompVal(c, -1, "preScale", 2, 1.000f)), "preBias" to floatArrayOf(getCompVal(c, -1, "preBias", 0, 0.000f), getCompVal(c, -1, "preBias", 1, 0.000f), getCompVal(c, -1, "preBias", 2, 0.000f)), "preDesat" to floatArrayOf(getCompVal(c, -1, "preDesat", 0, 0.000f), getCompVal(c, -1, "preDesat", 1, 0.000f), getCompVal(c, -1, "preDesat", 2, 0.000f))); val prePass = ShaderConfig.CustomPass(null, PRE_FS, 1f, 0, preUs); var lastSc = 1f; val ps = pp.keys.sorted().mapNotNull { i -> val p = pp[i] ?: return@mapNotNull null; val fc = fs[p["fragmentShader"] ?: return@mapNotNull null] ?: return@mapNotNull null; val vc = p["vertexShader"]?.let { fs[it] }; val rw = p["width"]?.toFloatOrNull() ?: 1f; val sc = maxOf(if (rw < 0f) minOf(-rw, 4f) else 1f, lastSc); lastSc = sc; val bl = p["blend"]?.toIntOrNull() ?: 0; val us = mutableMapOf<String, FloatArray>(); up.filterKeys { it.first == i }.forEach { (pr, uf) -> val t = uf["type"]?.firstOrNull() ?: "float"; val n = when(t){ "float2"->2; "float3"->3; "float4"->4; else->1 }; val ds = List(n) { idx -> if (n == 1) (uf["default"]?.firstOrNull()?.toFloatOrNull() ?: 0f) else (uf["default[$idx]"]?.firstOrNull()?.toFloatOrNull() ?: 0f) }; if (ds.isNotEmpty()) us[pr.second] = FloatArray(ds.size) { idx -> getCompVal(c, i, pr.second, idx, ds[idx]) } }; ShaderConfig.CustomPass(vc, fc, sc, bl, us) }; val g0=getCompVal(c,-1,"preGamma",0,1f); val s0=getCompVal(c,-1,"preScale",0,1f); val s1=getCompVal(c,-1,"preScale",1,1f); val s2=getCompVal(c,-1,"preScale",2,1f); val b0=getCompVal(c,-1,"preBias",0,0f); val b1=getCompVal(c,-1,"preBias",1,0f); val b2=getCompVal(c,-1,"preBias",2,0f); val d0=getCompVal(c,-1,"preDesat",0,0f); val d1=getCompVal(c,-1,"preDesat",1,0f); val d2=getCompVal(c,-1,"preDesat",2,0f); val preId=(g0==1f && s0==1f && s1==1f && s2==1f && b0==0f && b1==0f && b2==0f && d0==0f && d1==0f && d2==0f); val needsPre=(!preId && true) || ps.any { it.blendMode == 1 }; val baseList = if (needsPre) (listOf(prePass) + ps) else ps; val all = baseList.take(if (needsPre) getMaxPasses(c) else maxOf(getMaxPasses(c) - 1, 1)); return if (all.isNotEmpty()) ShaderConfig.Custom(all) else null } }
